import{bV as t,aL as e,u as o,G as p}from"./chunks/framework.ByYcXNJx.js";const c=JSON.parse('{"title":"疫情突然从严防到放开的小日记","description":"疫情突然从严防到放开的一些小感想","frontmatter":{"title":"疫情突然从严防到放开的小日记","date":"2022-12-18T08:00:00.000Z","cover":"https://oceroimagestore.metalstudio.top/img/20221217205007.png","tags":["2022大事件","疫情","养生","穴位"],"categories":["日记"],"description":"疫情突然从严防到放开的一些小感想","permalink":"/pages/443696"},"headers":[],"relativePath":"疫情从严防到突然放开的小日记.md","filePath":"疫情从严防到突然放开的小日记.md","lastUpdated":null}'),r={name:"疫情从严防到突然放开的小日记.md"};function i(s,a,l,n,d,_){return e(),o("div",null,[...a[0]||(a[0]=[p('<h1 id="疫情突然从严防到放开的小日记" tabindex="-1">疫情突然从严防到放开的小日记 <a class="header-anchor" href="#疫情突然从严防到放开的小日记" aria-label="Permalink to &quot;疫情突然从严防到放开的小日记&quot;">​</a></h1> <h2 id="前言" tabindex="-1">前言 <a class="header-anchor" href="#前言" aria-label="Permalink to &quot;前言&quot;">​</a></h2> <p>最近这几天周围的很多朋友都病了。包括老师啊，同学啊，等等等等。还是希望大家不要被阳上。</p> <h2 id="经过及分析" tabindex="-1">经过及分析 <a class="header-anchor" href="#经过及分析" aria-label="Permalink to &quot;经过及分析&quot;">​</a></h2> <p>一开始我还以为这个病毒只是攻你大肠经和肺经的。感觉像什么肾俞啊，中脘啊等穴位只是起到加强免疫力的作用。结果真是没想到，这个病毒不仅只是攻你大肠经和肺经的还包括其他经络</p> <p>事情是这样的</p> <p>当时某个群里面有人说他吃饭很痛，一开始我感觉应该是嗓子痛。结果不看不知道，一看吓一跳。他是胃疼</p> <p><img src="https://oceroimagestore.metalstudio.top/img/20221218105211.png" alt="截图"></p> <p>胃疼！这两个字触发了我当时的思绪。难怪在《感染者居家中医药干预指引》中的推拿康复方案里面写到中脘、足三里这两个穴位，还有足阳明胃经，足太阴脾经这两条经络。这回知道咋回事了。它现在的话要么是走肝然后去让脾胃遭殃（金克木，木克土）。也有可能顺便把脾胃之气给搅和遭殃了。</p> <p>《感染者居家中医药干预指引》的部分截图</p> <p><img src="https://oceroimagestore.metalstudio.top/img/20221218110334.png" alt=""></p> <p>再接着，我们补课的物理老师也不幸有了疑似症状。（线上）他是腰特别疼（感觉比腰断了还疼）。这又让我联想到了肾俞这个穴位</p> <p>肾俞是足太阳膀胱经的。是肾的腧穴，内应肾脏。而且能治腰痛。再加上发高烧什么的。我感觉是时候分享一些保健方法了</p> <p>（一不小心变成保健文章了)</p> <h2 id="保健方法" tabindex="-1">保健方法 <a class="header-anchor" href="#保健方法" aria-label="Permalink to &quot;保健方法&quot;">​</a></h2> <p>我个人来说的话我比较推崇的一些养生方法也是很常用的方法就是</p> <h3 id="_1-搓涌泉" tabindex="-1">1. 搓涌泉 <a class="header-anchor" href="#_1-搓涌泉" aria-label="Permalink to &quot;1. 搓涌泉&quot;">​</a></h3> <p>涌泉这个穴位，相信大家其实都对它很耳熟。它在足底的上三分之一和二三趾指缝的交点（你也可以把足趾向下弯曲，中间有个小坑的地方就是，也可以用人字形的方法来找穴）。我本人更喜欢的是劳宫搓涌泉。劳宫穴的话在手掌心。握拳的时候中指指到的那个地方就是。劳宫搓涌泉的话使得水火相济，有着很好的滋补作用。我不太纠结说我要搓多少下，只要感觉交底发热就达到相应的效果了。经常搓涌泉可以达到补足肾气明目等功效。做的时候要注意心无杂念</p> <p>（穴位附图）</p> <p>涌泉穴</p> <p><img src="https://oceroimagestore.metalstudio.top/img/20221218112738.png" alt=""></p> <p>劳宫穴</p> <p><img src="https://oceroimagestore.metalstudio.top/img/20221218112835.png" alt=""></p> <h3 id="_2-摩腹" tabindex="-1">2.摩腹 <a class="header-anchor" href="#_2-摩腹" aria-label="Permalink to &quot;2.摩腹&quot;">​</a></h3> <p>这个我感觉做完之后很舒服，尤其是手和肚皮之间接触的感觉很爽。我是比较习惯从肚脐作为中心然后慢慢向外扩散，之后再回到腹部这样的去摩腹。 当然做的时候也需要去心无杂念，感受手触摸到腹部皮肤的感觉</p>',49)])])}const m=t(r,[["render",i]]);export{c as __pageData,m as default};
